; ============================================== sub sameScale ====

sameScale:
; ---- scale = scale + height
        mov     ax, [scale]
        mov     bx, [height]
        add     ax, bx
        mov     [scale], ax
; ---- scale = scale - height
        mov     bx, [height]
        sub     ax, bx
        mov     [scale], ax
; ---- over = scale < height
        mov     bx, [height]
        cmp     ax, bx
        jge     .L1                         ; signed <
        mov     ax, 1
        jmp     .L2
.L1:
        xor     ax, ax
.L2:
        mov     [over], al                  ; narrowed to bool
        ret

; ============================================== sub counts ====

counts:
; ---- scale = scale * 3
        mov     ax, [scale]
        mov     bx, 3
        mul     bx                          ; low 16 bits are sign-agnostic
        mov     [scale], ax
; ---- scale = scale / 2
