        cwd                                 ; sign-extend AX into DX:AX
        idiv    bx
        mov     [scale], ax
; ---- scale = scale >> 1
        sar     ax, 1                       ; signed >>
        mov     [scale], ax
; ---- scale = -scale
        neg     ax
        mov     [scale], ax
        ret

; ============================================== sub constants ====

constants:
; ---- scale = i8.8( 3 )
