; ---- small = small * 2
        cbw                                 ; i8 -> i16
        shl     ax, 1                       ; * 2 is << 1
        mov     [small], al                 ; narrowed to i8
        ret

; ============================================== sub throughStorage ====

throughStorage:
; ---- table[0] = scale
        mov     ax, [scale]
        mov     [table], ax
; ---- scale = table[1]
