; ---- blob[0].weight = scale
        mov     [blob__weight], ax
; ---- scale = blob[1].weight
        mov     ax, [blob__weight + 2]
        mov     [scale], ax
; ---- scale = one
        mov     word [scale], 256
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int21:
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
